            while (rows.next()) {
                messages.add(new Message(rows.getLong("id"), Channel.valueOf(rows.getString("channel")),
                        rows.getString("to_address"), rows.getString("subject"), rows.getString("body"),
                        MessageStatus.valueOf(rows.getString("status"))));
            }
            return messages;
        }
    }
